import{_ as t,o,c as a,a4 as l}from"./chunks/framework.9tZL7ZIQ.js";const p=JSON.parse('{"title":"人生选择","description":"","frontmatter":{},"headers":[],"relativePath":"05_quotes/by-scene/人生选择.md","filePath":"05_quotes/by-scene/人生选择.md"}'),r={name:"05_quotes/by-scene/人生选择.md"};function u(c,e,q,s,_,i){return o(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="人生选择" tabindex="-1">人生选择 <a class="header-anchor" href="#人生选择" aria-label="Permalink to &quot;人生选择&quot;">​</a></h1><blockquote><p>&quot;做你热爱的事，成功会随之而来。如果你热爱你所做的，金钱只是副产品。&quot;——巴菲特</p></blockquote><hr><h2 id="核心金句" tabindex="-1">核心金句 <a class="header-anchor" href="#核心金句" aria-label="Permalink to &quot;核心金句&quot;">​</a></h2><blockquote><p>&quot;我这辈子做过最正确的决定，是找到了我热爱的工作。我每天踩着舞步去办公室，不是因为钱，而是因为热爱。&quot;</p></blockquote><blockquote><p>&quot;你和谁在一起度过你的工作时间很重要。找到那些让你变得更好的人，远离那些消耗你能量的人。&quot;</p></blockquote><blockquote><p>&quot;名气和财富不是成功的定义。对我来说，成功是：每天早上期待去工作，身边都是你信任和欣赏的人。&quot;</p></blockquote><blockquote><p>&quot;延迟满足是一种美德。我宁愿现在少花一点钱，换取未来更多的自由。&quot;</p></blockquote><blockquote><p>&quot;我从来没有把追求金钱作为目标。但财富自由确实给了我选择权——选择如何度过我的时间，选择支持哪些事情。&quot;</p></blockquote><hr><h2 id="出处说明" tabindex="-1">出处说明 <a class="header-anchor" href="#出处说明" aria-label="Permalink to &quot;出处说明&quot;">​</a></h2><p>以上部分语录来自巴菲特公开演讲和访谈。</p><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>这些金句主要来自以下年份致股东信和公开访谈，核心语录可参考：</p><ul><li><a href="/01_letters/1986年/翻译">/01_letters/1986年/翻译</a></li><li><a href="/01_letters/1990年/翻译">/01_letters/1990年/翻译</a></li></ul><blockquote><p>部分语录来自巴菲特公开演讲和访谈，未收录于致股东信原文。</p></blockquote>',16)])])}const h=t(r,[["render",u]]);export{p as __pageData,h as default};
